"""Optional standalone browser demo for GitHub Pages; no API key, no backend."""
from pathlib import Path
import json
from foodflow.data import generate_demo_orders

data = generate_demo_orders().where(lambda d: d.notna(), None).to_dict(orient="records")
# Explicit conversion to plain JSON handles pandas NaN missing values via clean transformation.
for row in data:
    if row['status'] == 'cancelled':
        row['actual_minutes'] = None

page = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FoodFlow AI — Operations Copilot</title>
<style>
:root{color-scheme:dark;--bg:#0d0c10;--panel:#1b151b;--panel2:#241921;--line:#3b2d39;--muted:#a6a0ad;--white:#f8f4fa;--accent:#ff2857;--accent2:#fd7c91;--good:#52d5b2}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 100% 0%,#331621 0,transparent 34%),var(--bg);color:var(--white);font:15px/1.5 'Segoe UI',system-ui,-apple-system,sans-serif}
.wrap{max-width:1320px;margin:auto;padding:34px 28px 65px}.top{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:48px}.brand{font-size:24px;font-weight:800;letter-spacing:-1.1px}.brand span{color:var(--accent)}.tag{border:1px solid #69404c;border-radius:80px;padding:7px 13px;font-size:12px;color:#ffc4d1}.hero{display:flex;flex-wrap:wrap;gap:24px;justify-content:space-between;align-items:end;margin-bottom:28px}h1{font-size:clamp(30px,5vw,52px);line-height:1.08;letter-spacing:-2px;margin:0 0 12px}h1 b{color:var(--accent)}.muted{color:var(--muted);margin:0}.controls{display:flex;gap:12px;align-items:end}label{display:flex;flex-direction:column;gap:8px;font-size:12px;color:var(--muted)}select,.btn{background:var(--panel2);color:#fff;border:1px solid #513544;border-radius:10px;padding:11px 15px;font:inherit;cursor:pointer}.btn{background:var(--accent);border-color:var(--accent);font-weight:700}.btn:hover{filter:brightness(1.13)}.notice{border-left:3px solid var(--accent);padding:10px 15px;color:#eacfd6;background:#331a24;margin-bottom:24px;border-radius:0 9px 9px 0;font-size:13px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.kpi,.card{border:1px solid var(--line);border-radius:15px;background:linear-gradient(155deg,#241923,#17131a);padding:20px}.kpi small{color:var(--muted)}.kpi h2{font-size:clamp(24px,3vw,37px);margin:11px 0 5px;letter-spacing:-1.4px}.kpi footer{color:#e1b4c0;font-size:12px}.panelgrid{display:grid;grid-template-columns:1.15fr .85fr;gap:16px;margin-top:16px}.card h3{font-size:17px;letter-spacing:-.4px;margin:0 0 4px}.card header{margin-bottom:20px}#trend{width:100%;height:255px}#bars{width:100%;height:255px}.section{margin:30px 0 14px;display:flex;justify-content:space-between;gap:15px;align-items:center}.section h2{font-size:21px;margin:0}.section small{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid #322833}th{color:var(--muted);font-weight:500;font-size:12px;text-transform:uppercase;letter-spacing:.6px}td{font-variant-numeric:tabular-nums}tr:last-child td{border:none}.pill{padding:5px 9px;border-radius:100px;background:#4d2334;color:#ffa3bb;font-size:12px;font-weight:700}.alerts{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.alert h4{margin:0 0 10px;font-size:16px}.alert{background:#241821;border:1px solid #563443;border-radius:13px;padding:20px}.alert p{color:#d1bac3;font-size:14px}.tiny{font-size:12px;color:var(--muted)}.footer{color:var(--muted);font-size:12px;margin-top:35px;border-top:1px solid var(--line);padding-top:20px}.kbd{background:#2c2630;border:1px solid #493a49;padding:2px 6px;border-radius:4px;font-family:monospace}@media(max-width:900px){.panelgrid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}.alerts{grid-template-columns:1fr 1fr}}@media(max-width:600px){.wrap{padding:20px 14px}.kpis,.alerts{grid-template-columns:1fr}.top{margin-bottom:25px}.controls{width:100%;justify-content:space-between}.section{align-items:start;flex-direction:column}td,th{padding:9px 5px;font-size:12px}.tag{display:none}}
</style></head><body><main class="wrap">
<div class="top"><div class="brand">🍽️ FoodFlow <span>AI</span></div><div class="tag">AI BUILDER · DEMONSTRAÇÃO INDEPENDENTE</div></div>
<div class="hero"><div><h1>Transforme dados em<br><b>decisões operacionais.</b></h1><p class="muted">Dashboard interativo de performance de delivery e priorização inteligente.</p></div><div class="controls"><label>REGIÃO<select id="region"><option>Todas</option><option>Centro</option><option>Zona Norte</option><option>Zona Sul</option><option>Zona Oeste</option></select></label><button class="btn" id="export">↓ Exportar JSON</button></div></div>
<div class="notice">🔬 <b>Dados 100% sintéticos.</b> Esta página é uma demonstração estática de portfólio. Não pertence ao iFood. O aplicativo Python completo inclui API, automação e agente Claude opcional.</div>
<section class="kpis"><div class="kpi"><small>Pedidos analisados</small><h2 id="orders">—</h2><footer>Amostra de demonstração</footer></div><div class="kpi"><small>Taxa de cancelamento</small><h2 id="cancel">—</h2><footer>Cancelados / total</footer></div><div class="kpi"><small>Taxa de entregas atrasadas</small><h2 id="late">—</h2><footer>Atrasos / entregas</footer></div><div class="kpi"><small>Atraso positivo médio</small><h2 id="delay">—</h2><footer>Minutos nas entregas</footer></div></section>
<section class="panelgrid"><article class="card"><header><h3>Volume de pedidos por dia</h3><p class="tiny">Distribuição temporal da amostra</p></header><svg viewBox="0 0 580 255" id="trend" role="img" aria-label="Linha de volume de pedidos por dia"></svg></article><article class="card"><header><h3>Ranking de risco operacional</h3><p class="tiny">Score heurístico: atrasos × 0,65 + cancelamentos × 0,35</p></header><svg id="bars" viewBox="0 0 400 255" role="img" aria-label="Gráfico de barras do risco por loja"></svg></article></section>
<div class="section"><h2>🔎 Diagnóstico por restaurante</h2><small>Indicadores calculados no navegador · sem servidor</small></div><article class="card" style="overflow-x:auto"><table><thead><tr><th>Loja</th><th>Pedidos</th><th>Atraso</th><th>Cancelamento</th><th>Score</th></tr></thead><tbody id="ranking"></tbody></table></article>
<div class="section"><h2>🚨 Alertas e planos de ação</h2><small>Hipóteses, não ações executadas</small></div><div id="alerts" class="alerts"></div>
<div class="footer">Projeto educacional de portfólio • Engine Python + Streamlit + FastAPI + agente Anthropic opcional • Nenhum resultado comercial ou economia de horas foi medido. <span class="kbd">index.html</span> é a vitrine offline; veja o README para a aplicação integral.</div>
</main>
<script>const ORDERS=__ORDERS__;
const $=s=>document.querySelector(s);const nfmt=n=>new Intl.NumberFormat('pt-BR').format(n);const pct=v=>v.toFixed(1)+'%';const svgNS='http://www.w3.org/2000/svg';const mk=(tag,attrs,text)=>{const e=document.createElementNS(svgNS,tag);for(const k in attrs)e.setAttribute(k,attrs[k]);if(text!==undefined)e.textContent=text;return e};
function kpi(rows){let del=rows.filter(o=>o.status==='delivered'),c=rows.length-del.length;let late=del.filter(o=>o.actual_minutes>o.promised_minutes).length;let avg=del.reduce((s,o)=>s+Math.max(0,o.actual_minutes-o.promised_minutes),0)/(del.length||1);return{orders:rows.length,cancel:100*c/(rows.length||1),late:100*late/(del.length||1),delay:avg}}
function show(){const region=$('#region').value,rows=ORDERS.filter(o=>region==='Todas'||o.region===region),m=kpi(rows);$('#orders').textContent=nfmt(m.orders);$('#cancel').textContent=pct(m.cancel);$('#late').textContent=pct(m.late);$('#delay').textContent=m.delay.toFixed(1)+' min';
const ids=[...new Set(rows.map(o=>o.restaurant_id))],store=ids.map(id=>{let orders=rows.filter(o=>o.restaurant_id===id),m=kpi(orders);return{id,...m,score:.65*m.late+.35*m.cancel}}).sort((a,b)=>b.score-a.score);window.lastReport={kpis:m,ranking:store,dataset:'Dados sintéticos',note:'Sem relação com operações reais do iFood'};
$('#ranking').innerHTML=store.map((s,i)=>`<tr><td><b>${s.id}</b></td><td>${s.orders}</td><td>${pct(s.late)}</td><td>${pct(s.cancel)}</td><td><span class="pill">${s.score.toFixed(1)}</span></td></tr>`).join('');
const alerts=[];store.slice(0,5).forEach(s=>{if(s.orders>=20&&s.late>=40)alerts.push({store:s.id,title:'Atrasos acima do limiar',evidence:`${pct(s.late)} de entregas acima do prazo.`,action:'Investigar preparo, capacidade e demanda por faixa horária.'});if(s.orders>=20&&s.cancel>=10)alerts.push({store:s.id,title:'Cancelamentos elevados',evidence:`${pct(s.cancel)} de pedidos cancelados.`,action:'Revisar causas de cancelamento, estoque e confirmação.'})});if(!alerts.length)alerts.push({store:'Todas',title:'Sem alerta acima do limiar',evidence:'Regras não foram ativadas.',action:'Seguir monitorando os KPIs.'});$('#alerts').innerHTML=alerts.map(a=>`<article class="alert"><div class="pill" style="display:inline-block;margin-bottom:13px">${a.store}</div><h4>${a.title}</h4><p>${a.evidence}</p><div class="tiny">PROPOSTA</div><p>${a.action}</p></article>`).join('');
const daily={};rows.forEach(o=>{const d=o.created_at.slice(5,10);daily[d]=(daily[d]||0)+1});const points=Object.entries(daily).sort(([a],[b])=>a.localeCompare(b));const trend=$('#trend');trend.replaceChildren();const W=580,H=255,p=40,max=Math.max(...points.map(x=>x[1]),1);for(let i=0;i<4;i++){let y=H-25-(i*(H-55)/3);trend.append(mk('line',{x1:p,y1:y,x2:W-10,y2:y,stroke:'#3d303c'}));trend.append(mk('text',{x:5,y:y+4,fill:'#ad9faa','font-size':'12'},Math.round(max*i/3).toString()))}const coords=points.map(([d,v],i)=>[p+i*(W-60)/Math.max(1,points.length-1),H-25-v/max*(H-65)]);trend.append(mk('polyline',{points:coords.map(x=>x.join(',')).join(' '),fill:'none',stroke:'#ff2857','stroke-width':3,'stroke-linecap':'round','stroke-linejoin':'round'}));coords.forEach((pt,i)=>{const c=mk('circle',{cx:pt[0],cy:pt[1],r:4,fill:'#ff2857'});const title=mk('title',{},`${points[i][0]}: ${points[i][1]} pedidos`);c.appendChild(title);trend.append(c)});for(let i=0;i<points.length;i+=Math.max(1,Math.ceil(points.length/5))){trend.append(mk('text',{x:coords[i][0],y:H-5,fill:'#b4a5b1','font-size':'11','text-anchor':'middle'},points[i][0]))}
const bars=$('#bars');bars.replaceChildren();store.slice(0,5).forEach((s,i)=>{const y=12+i*48;bars.append(mk('text',{x:5,y:y+15,fill:'#e1d5df','font-size':'13'},s.id));bars.append(mk('rect',{x:95,y:y,width:245,height:21,rx:6,fill:'#302330'}));bars.append(mk('rect',{x:95,y:y,width:Math.max(2,245*s.score/100),height:21,rx:6,fill:'#ff2857'}));bars.append(mk('text',{x:350,y:y+16,fill:'#f8d0da','font-size':'13'},s.score.toFixed(1)))})}
$('#region').addEventListener('change',show);$('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(window.lastReport,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='foodflow-demo.json';a.click();URL.revokeObjectURL(url)});show();
</script></body></html>'''
page = page.replace('__ORDERS__', json.dumps(data, separators=(',', ':'), ensure_ascii=False, allow_nan=False))
Path('index.html').write_text(page, encoding='utf-8')
print('Static HTML written:', Path('index.html').stat().st_size, 'bytes')
